/**
 * Calculate invoice totals.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate?: number }>, voucher?: { code: string, amount: number } }} invoice
 * @returns {{ subtotal: number, discount: number, vat: number, voucher: number, total: number }}
 */
export function invoiceTotals(invoice) {
  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
  const discount = invoice.lines.reduce((sum, line) => {
    const lineSubtotal = lineTotal(line);
    const lineDiscount = lineSubtotal * (line.discountPercent ?? 0) / 100;
    const lineAmountAfterDiscount = lineSubtotal - lineDiscount;
    const bulkDiscount = line.qty >= 10 ? lineAmountAfterDiscount * 2.5 / 100 : 0;
    return sum + Math.max(0, lineDiscount + bulkDiscount);
  }, 0);
  const vat = invoice.lines.reduce((sum, line) => {
    const lineSubtotal = lineTotal(line);
    const lineDiscount = lineSubtotal * (line.discountPercent ?? 0) / 100;
    const lineAmountAfterDiscount = lineSubtotal - lineDiscount;
    const bulkDiscount = line.qty >= 10 ? lineAmountAfterDiscount * 2.5 / 100 : 0;
    const lineAmountAfterAllDiscounts = lineAmountAfterDiscount - bulkDiscount;
    const lineVAT = lineAmountAfterAllDiscounts * (line.vatRate ?? 0) / 100;
    return sum + roundCents(Math.max(0, lineVAT));
  }, 0);
  const voucher = invoice.voucher?.amount ?? 0;
  const total = Math.max(0, subtotal - discount + vat - voucher);
  return {
    subtotal: Math.max(0, subtotal),
    discount: Math.max(0, discount),
    vat: Math.max(0, vat),
    voucher,
    total,
  };
}

