test('invoiceTotals handles edge case with no lines', () => {
  const invoice = {
    lines: [],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 0);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 0);
  assert.equal(totals.voucher, 0);
  assert.equal(totals.total, 0);
});

test('invoiceTotals applies bulk discount (2.5%) for qty >= 10', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
  };
  const totals = invoiceTotals(invoice);
  // Subtotal: 10 * 1000 = 10000
  // Line discount: 10000 * 0 / 100 = 0
  // After first discount: 10000
  // Bulk discount (2.5%): 10000 * 2.5 / 100 = 250
  // Total discount: 250
  // Total: 10000 - 250 = 9750
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 250);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 9750);
});

test('invoiceTotals does not apply bulk discount for qty < 10', () => {
  const invoice = {
    lines: [{ qty: 9, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
  };
  const totals = invoiceTotals(invoice);
  // Subtotal: 9 * 1000 = 9000
  // No line discount, no bulk discount
  // Total: 9000
  assert.equal(totals.subtotal, 9000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.total, 9000);
});

test('invoiceTotals applies bulk discount with qty = 10 exactly', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 500, discountPercent: 0, vatRate: 0 }],
  };
  const totals = invoiceTotals(invoice);
  // Subtotal: 10 * 500 = 5000
  // Bulk discount: 5000 * 2.5 / 100 = 125
  assert.equal(totals.subtotal, 5000);
  assert.equal(totals.discount, 125);
  assert.equal(totals.total, 4875);
});

test('invoiceTotals applies bulk discount after line discount', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, discountPercent: 10, vatRate: 0 }],
  };
  const totals = invoiceTotals(invoice);
  // Subtotal: 10 * 1000 = 10000
  // Line discount: 10000 * 10 / 100 = 1000
  // After first discount: 9000
  // Bulk discount (2.5%): 9000 * 2.5 / 100 = 225
  // Total discount: 1000 + 225 = 1225
  // Total: 10000 - 1225 = 8775
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 1225);
  assert.equal(totals.total, 8775);
});

test('invoiceTotals calculates VAT after both discounts', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, discountPercent: 10, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  // Subtotal: 10 * 1000 = 10000
  // Line discount: 10000 * 10 / 100 = 1000
  // After first discount: 9000
  // Bulk discount: 9000 * 2.5 / 100 = 225
  // After all discounts: 8775
  // VAT (21%): 8775 * 21 / 100 = 1842.75, rounded = 1843
  // Total: 8775 + 1843 = 10618
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 1225);
  assert.equal(totals.vat, 1843);
  assert.equal(totals.total, 10618);
});

test('invoiceTotals bulk discount with multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 0 },
      { qty: 5, unitPrice: 1000, discountPercent: 0, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Line 1: 10 * 1000 = 10000, bulk discount: 250
  // Line 2: 5 * 1000 = 5000, no bulk discount
  // Total discount: 250
  // Subtotal: 15000, Total: 14750
  assert.equal(totals.subtotal, 15000);
  assert.equal(totals.discount, 250);
  assert.equal(totals.total, 14750);
});

test('invoiceTotals bulk discount on all lines when all >= 10', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 0 },
      { qty: 15, unitPrice: 1000, discountPercent: 0, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Line 1: 10 * 1000 = 10000, bulk discount: 250
  // Line 2: 15 * 1000 = 15000, bulk discount: 375
  // Total discount: 625
  // Subtotal: 25000, Total: 24375
  assert.equal(totals.subtotal, 25000);
  assert.equal(totals.discount, 625);
  assert.equal(totals.total, 24375);
});

test('invoiceTotals bulk discount with line discount and VAT', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 5, vatRate: 21 },
      { qty: 8, unitPrice: 1000, discountPercent: 5, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Line 1: 10 * 1000 = 10000
  //   Line discount: 500
  //   After: 9500
  //   Bulk discount: 237.5
  //   After all: 9262.5
  //   VAT: 9262.5 * 21 / 100 = 1945.125 -> 1945
  // Line 2: 8 * 1000 = 8000
  //   Line discount: 400
  //   After: 7600
  //   No bulk discount
  //   VAT: 7600 * 21 / 100 = 1596
  // Subtotal: 18000
  // Total discount: 500 + 237.5 + 400 = 1137.5
  // Total VAT: 1945 + 1596 = 3541
  // Total: 18000 - 1137.5 + 3541 = 20403.5
  assert.equal(totals.subtotal, 18000);
  assert.equal(totals.discount, 1137.5);
  assert.equal(totals.vat, 3541);
  assert.equal(totals.total, 20403.5);
});

test('invoiceTotals bulk discount does not apply to qty 9', () => {
  const invoice = {
    lines: [{ qty: 9, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
  };
  const totals = invoiceTotals(invoice);
  // Subtotal: 9000
  // No bulk discount (qty < 10)
  assert.equal(totals.subtotal, 9000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.total, 9000);
});

test('invoiceTotals bulk discount applies to qty 11', () => {
  const invoice = {
    lines: [{ qty: 11, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
  };
  const totals = invoiceTotals(invoice);
  // Subtotal: 11000
  // Bulk discount: 11000 * 2.5 / 100 = 275
  assert.equal(totals.subtotal, 11000);
  assert.equal(totals.discount, 275);
  assert.equal(totals.total, 10725);
});

test('invoiceTotals bulk discount with 100% line discount still applies', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, discountPercent: 100, vatRate: 0 }],
  };
  const totals = invoiceTotals(invoice);
  // Subtotal: 10000
  // Line discount: 10000
  // After first discount: 0
  // Bulk discount: 0 * 2.5 / 100 = 0
  // Total discount: 10000
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 10000);
  assert.equal(totals.total, 0);
});

test('invoiceTotals bulk discount with high quantity', () => {
  const invoice = {
    lines: [{ qty: 100, unitPrice: 500, discountPercent: 0, vatRate: 0 }],
  };
  const totals = invoiceTotals(invoice);
  // Subtotal: 100 * 500 = 50000
  // Bulk discount: 50000 * 2.5 / 100 = 1250
  assert.equal(totals.subtotal, 50000);
  assert.equal(totals.discount, 1250);
  assert.equal(totals.total, 48750);
});

test('invoiceTotals bulk discount does not double-apply', () => {
  const invoice = {
    lines: [{ qty: 20, unitPrice: 500, discountPercent: 0, vatRate: 0 }],
  };
  const totals = invoiceTotals(invoice);
  // Subtotal: 20 * 500 = 10000
  // Bulk discount (only once): 10000 * 2.5 / 100 = 250
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 250);
  assert.equal(totals.total, 9750);
});

