test('invoiceTotals subtracts voucher from total', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const totalsBefore = invoiceTotals(r.value);

  const vouched = applyVoucher(r.value, { code: 'SAVE10', amount: 1000 });
  const totalsAfter = invoiceTotals(vouched.value);

  assert.equal(totalsAfter.voucher, 1000);
  assert.equal(totalsAfter.total, totalsBefore.total - 1000);
});

test('invoiceTotals total formula with voucher', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const vouched = applyVoucher(r.value, { code: 'SAVE10', amount: 2000 });
  const totals = invoiceTotals(vouched.value);

  // C-001 is gold tier (5% discount)
  // Subtotal: 5 * 8500 = 42500
  // Discount: 42500 * 5% = 2125
  // After discount: 40375
  // VAT: 40375 * 21% = 8478.75 -> 8479
  // Total before voucher: 40375 + 8479 = 48854
  // Total after voucher: 48854 - 2000 = 46854
  assert.equal(totals.subtotal, 42500);
  assert.equal(totals.discount, 2125);
  assert.equal(totals.vat, 8479);
  assert.equal(totals.voucher, 2000);
  assert.equal(totals.total, 46854);
  assert.equal(totals.total, totals.subtotal - totals.discount + totals.vat - totals.voucher);
});

test('invoiceTotals clamps negative total at 0 with voucher', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const totals = invoiceTotals(r.value);
  const voucherAmount = totals.total + 10000;

  const vouched = applyVoucher(r.value, { code: 'BIGDISCOUNT', amount: voucherAmount });
  const totalsAfter = invoiceTotals(vouched.value);

  assert.equal(totalsAfter.total, 0);
});

test('applyVoucher can be called with large amounts', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const result = applyVoucher(r.value, { code: 'HUGE', amount: 999999999 });
  assert.equal(result.ok, true);
  assert.equal(result.value.voucher.amount, 999999999);
});

test('applyVoucher preserves all other invoice properties', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  const result = applyVoucher(r.value, { code: 'SAVE10', amount: 1000 });

  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.issueDate, '2023-10-15');
  assert.equal(result.value.status, 'draft');
  assert.equal(result.value.terms, 'NET14');
  assert.equal(result.value.dueDate, '2023-10-29');
  assert.equal(result.value.lines.length, 1);
});

