      { sku: 'ICON-SET', qty: 3 },
    ],
  });
  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');
  // Line structure: DRAFT, customer, 3 items, VAT, total = 7 lines
  assert.equal(lines.length, 7);
  assert.ok(lines[2].includes('Design work (hour)'));
  assert.ok(lines[3].includes('Copywriting (hour)'));
  assert.ok(lines[4].includes('Icon set (24 icons)'));
  // Subtotal: 5*8500 + 2*6000 + 3*980 = 57440
  // VAT: 42500*0.21 + 12000*0.21 + 2940*0.21 = 8925 + 2520 + 617.4 = 12062.4, rounded = 12062
  // Total: 57440 + 12062 = 69502
  assert.ok(lines[6].includes('€695.02'));
});

test('renderInvoiceText calculates correct totals', () => {
  const r = createInvoice({
    customerId: 'C-002', // Standard tier (0% discount)
