      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'DEV-HOUR', qty: 5 },
    ],
  });
  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');
  // Subtotal: 10*8500 + 5*9500 = 85000 + 47500 = 132500
  // VAT: 85000*0.21 + 47500*0.21 = 17850 + 9975 = 27825
  // Total: 132500 + 27825 = 160325 = €1,603.25
  assert.ok(lines[lines.length - 1].includes('€1,603.25'));
});

test('renderInvoiceText clamps negative totals at 0', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2023-10-15',
    status: 'draft',
    lines: [
      {
        sku: 'DES-HOUR',
        name: 'Design work (hour)',
        qty: -5,
        unitPrice: 8500,
        vatRate: 21,
        discountPercent: 0,
      },
    ],
  };
  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  // -5 * 8500 = -42500, but clamped at 0
  assert.ok(lines[2].includes('-5 x'));
  assert.ok(lines[2].includes('-€425.00'));
  assert.ok(lines[lines.length - 1].includes('€0.00'));
});

